// app/lib/db.ts

// Using globalThis to maintain state across module reloads in dev mode
declare global {
  var _notifications: boolean | undefined;
}

export const db = {
  getNotifications: async () => {
    // simulate DB delay
    await new Promise((resolve) => setTimeout(resolve, 100));
    return globalThis._notifications ?? false;
  },
  toggleNotifications: async () => {
    // simulate DB delay
    await new Promise((resolve) => setTimeout(resolve, 100));
    // Toggle the value
    globalThis._notifications = !(globalThis._notifications ?? false);
    return globalThis._notifications;
  },
};

'use server';

import { revalidatePath } from 'next/cache';
import { db } from './lib/db';

export async function toggleNotificationPreference() {
  // Simulate database operation
  await db.toggleNotifications();

  // Revalidate the current path to refresh the data
  revalidatePath('/');
}

'use client';

import { useTransition } from 'react';
import { toggleNotificationPreference } from './actions';

export function NotificationToggle({ enabled }: { enabled: boolean }) {
  const [isPending, startTransition] = useTransition();

  return (
    <button
      onClick={() => {
        startTransition(async () => {
          await toggleNotificationPreference();
        });
      }}
      disabled={isPending}
      className="px-4 py-2 bg-blue-500 text-white rounded disabled:opacity-50"
    >
      {enabled ? 'Notifications: ON' : 'Notifications: OFF'}
      {isPending ? ' (Updating...)' : ''}
    </button>
  );
}

import { db } from './lib/db';
import { NotificationToggle } from './notification-toggle';

export default async function Page() {
  const enabled = await db.getNotifications();

  return (
    <main className="p-8">
      <h1 className="text-2xl font-bold mb-4">Notification Settings</h1>
      <div className="bg-gray-100 p-6 rounded-lg shadow-sm">
        <p className="mb-4">
          Current preference: <strong>{enabled ? 'ON' : 'OFF'}</strong>
        </p>
        <NotificationToggle enabled={enabled} />
      </div>
    </main>
  );
}

